import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Next.js and UI architecture","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/next.md","filePath":"frontend/next.md"}'),i={name:"frontend/next.md"};function o(s,e,c,d,l,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="next-js-and-ui-architecture" tabindex="-1">Next.js and UI architecture <a class="header-anchor" href="#next-js-and-ui-architecture" aria-label="Permalink to “Next.js and UI architecture”">​</a></h1><p>Prerequisites: <a href="./react.html">React ownership</a>, HTTP/status/cookies, unknown-input validation and server authorization. Teaching baseline: <strong>Next.js 16.4.3 App Router, React 19.3.0, Node 24.18.0</strong>, official docs checked 2026-10-27. Recheck patched versions and deployment support before using these examples in a real service.</p><h2 id="recommended-order" tabindex="-1"><span class="hub-section-number">1 </span>Recommended order <a class="header-anchor" href="#recommended-order" aria-label="Permalink to “1 Recommended order”">​</a></h2><ol><li><a href="./../senior_growth/React/next-app-router.html">App Router, safe DTOs and route states</a>.</li><li><a href="./../senior_growth/React/next-server-security.html">Sessions, server data access and mutations</a>.</li><li><a href="./../senior_growth/React/next-deployment-and-assets.html">Metadata, assets and deployment assumptions</a>.</li><li><a href="./../senior_growth/React/application_struvture.html">Application ports and boundaries</a> → <a href="./../senior_growth/React/design-system-contracts.html">component/token contracts</a> → <a href="./../senior_growth/React/design-system-release.html">stories, versioning and consumer migration</a>.</li><li><a href="./../senior_growth/EngX_Quality/Large_Data_Workflow.html">Large-data state ownership</a> and <a href="./../senior_growth/EngX_Quality/Rendering_and_Capability_Workflows.html">rendering/capability decisions</a> when the product requires them.</li></ol><h2 id="choose-server-client-boundaries-by-responsibility" tabindex="-1"><span class="hub-section-number">2 </span>Choose server/client boundaries by responsibility <a class="header-anchor" href="#choose-server-client-boundaries-by-responsibility" aria-label="Permalink to “2 Choose server/client boundaries by responsibility”">​</a></h2><p>Server Components can await protected data and keep server implementation out of the client module graph. Client Components own browser interactions, state and Effects; their initial HTML may still be rendered on the server. <code>use client</code> marks a dependency boundary, not a promise of browser-only initial execution. Project safe fields before crossing it; hidden client props are still delivered data.</p><p>A server layout is not a complete authorization boundary for every descendant action. Check actor, resource scope and current version in the data operation itself. Treat Route Handlers and Server Actions as externally invocable mutation boundaries; validate their inputs and enforce the appropriate CSRF policy. A UI guard and CORS do not substitute for that decision.</p><h2 id="rendering-and-caching-are-separate-contracts" tabindex="-1"><span class="hub-section-number">3 </span>Rendering and caching are separate contracts <a class="header-anchor" href="#rendering-and-caching-are-separate-contracts" aria-label="Permalink to “3 Rendering and caching are separate contracts”">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>Decision</th></tr></thead><tbody><tr><td>Client navigation cache</td><td>What the browser may reuse during navigation</td></tr><tr><td>Public server data/route cache</td><td>Shared freshness, invalidation and deployment store</td></tr><tr><td>Private request data</td><td>Actor-specific authorization and isolation; avoid accidental shared caching</td></tr><tr><td>HTTP/CDN cache</td><td>Response policy, keys and trusted proxy behavior</td></tr></tbody></table><p>The public reference deliberately sets <code>cacheComponents:false</code>. Current create-next-app defaults can enable Cache Components and Partial Prefetching; do not apply the previous-model fetch/route advice to that different model by accident. Caching documentation and upgrade guidance must match the pinned configuration.</p><p>router.refresh requests fresh route output but does not invalidate every server cache. Time-based revalidation is not a periodic job or instant write visibility. Stale-while-revalidate tag invalidation differs from Server Action updateTag/read-your-writes. Check clean production requests and instrumented upstream versions; the fixed public array cannot prove a data-cache freshness policy.</p><p>Missing data differs from operational failure. A streamed missing route can return an already-committed 200 while rendering not-found UI; test actual status and indexing behavior. Current error retry is stable from 16.3 and refetches/re-renders; reset has a narrower error-state-reset contract. Expected validation errors should be returned as safe data.</p><h2 id="ui-architecture-is-an-enforceable-contract" tabindex="-1"><span class="hub-section-number">4 </span>UI architecture is an enforceable contract <a class="header-anchor" href="#ui-architecture-is-an-enforceable-contract" aria-label="Permalink to “4 UI architecture is an enforceable contract”">​</a></h2><p>A component API specifies state ownership, event meaning, ref target, native semantics, supported styling hooks and compatibility. Keep Button and Link separate until polymorphism has a demonstrated need. Tokens express semantic design roles; generated types alone cannot prove contrast or first-paint theme agreement.</p><p>Organize by a small feature/application boundary before introducing a framework of abstractions. UI consumes a port; the application edge composes network/storage adapters. A direct-import lint rule is useful but not a resolved dependency-graph proof. Keep migrations incremental, preserve consumer behavior and define rollback before removing an old token/prop.</p><p>A static export cannot execute authenticated request-time handlers/actions, cookie reads or a Node image/ISR service. A Node deployment needs durable state, shared-cache/invalidation decisions where applicable, trusted ingress, runtime secrets and asset/CDN ownership. Public build-time environment values are not runtime secrets. Use the existing Node deployment material for infrastructure mechanisms.</p><p><a href="./../workbench/frontend/next/">Workbench</a> separates a runnable public application from security integration fragments. <a href="./../practice/frontend/f06-next.html">F06</a> defines the private/cache/deployment exercises without claiming they have run.</p><p>Official references: <a href="https://nextjs.org/docs/app/getting-started/server-and-client-components" target="_blank" rel="noreferrer">Server/Client Components</a>, <a href="https://nextjs.org/docs/app/getting-started/caching" target="_blank" rel="noreferrer">caching</a>, <a href="https://nextjs.org/docs/app/api-reference/file-conventions/error" target="_blank" rel="noreferrer">error APIs</a>, <a href="https://nextjs.org/docs/app/guides/authentication" target="_blank" rel="noreferrer">authentication</a>, <a href="https://nextjs.org/docs/app/guides/static-exports" target="_blank" rel="noreferrer">static export</a>. See <a href="./verification.html">verification and limits</a>.</p>',18)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
